    public class Event_Bounty : Event
    {
        //Event Instance
        public Bounty I { get; set; } = new Bounty();

        //Variable Generation
        public override void Generate(object O)
        {
            try
            {
                Variables.Record(Name + "_PilotName", I.PilotName_Localised);           //Pilot's Name
                Variables.Record(Name + "_Victim", I.Target);                           //Bounty Holder
                Variables.Record(Name + "_VictimFaction", I.VictimFaction_Localised);   //Holder's Faction
                Variables.Record(Name + "_Shared", I.SharedWithOthers);                 //In a Wing

                //Skimmer
                if (I.Reward != -1)
                {
                    Variables.Record(Name + "_Vehicle", "Skimmer");
                    Variables.Record(Name + "_VehicleName", "Skimmer");
                    Variables.Record(Name + "_Reward", I.Reward);
                }

                //Ship
                else
                {
                    Variables.Record(Name + "_Vehicle", "Ship");
                    Variables.Record(Name + "_VehicleName", I.Target_Localised);
                    Variables.Record(Name + "_Reward", I.TotalReward);
                }
            }
            catch (Exception ex)
            {
                ExceptionGenerate(Name, ex);
            }
        }

        //Plugin Logic Preparations
        public override void Prepare(object O)
        {
            try
            {
                //Update Event Instance
                I = (Bounty)O;
            }
            catch (Exception ex)
            {
                ExceptionPrepare(Name, ex);
            }
        }

        //Plugin Logic Process
        public override void Process(object O)
        {
            try
            {
                //Update Bounty Status Object
                IStatus.Bounty.Update(I);

                //Bounty Audio
                IResponse.Bounty.Collected(                    
                    ICheck.Initialized(ClassName),                          //Check Plugin Initialized
                    ICheck.Report.CollectedBounty(ClassName, true, true));  //Check Bounty Reports Enabled
            }
            catch (Exception ex)
            {
                ExceptionProcess(Name, ex);
            }
